import{_ as s,a as t,b as a,c as i,d as n,e as r,f as o,g as l,h as p}from"./chunks/events.DLZbqLJC.js";import{_ as d,o as c,c as u,a3 as h}from"./chunks/framework.BlfGB29P.js";const y=JSON.parse('{"title":"USB Extender pour Home Assistant","description":"Relier des touches USB, Stream Deck et claviers à macros à trois courtiers MQTT. Installation illustrée, apprentissage, topics et résultats pratiques.","frontmatter":{"title":"USB Extender pour Home Assistant","description":"Relier des touches USB, Stream Deck et claviers à macros à trois courtiers MQTT. Installation illustrée, apprentissage, topics et résultats pratiques."},"headers":[],"relativePath":"fr/projects/usb-extender/index.md","filePath":"fr/projects/usb-extender/index.md","lastUpdated":1795267108000}'),m={name:"fr/projects/usb-extender/index.md"};function g(k,e,b,v,f,F){return c(),u("div",null,[...e[0]||(e[0]=[h('<h1 id="usb-extender-pour-home-assistant" tabindex="-1">USB Extender pour Home Assistant <a class="header-anchor" href="#usb-extender-pour-home-assistant" aria-label="Permalink to &quot;USB Extender pour Home Assistant&quot;">​</a></h1><p><strong>0.1.5 · Raspberry Pi · Mise à jour du 21 novembre 2026</strong></p><p>Un clavier USB connecté au Raspberry Pi peut servir de commande pour Home Assistant ou ioBroker. USB Extender lit les entrées et les publie vers <strong>trois courtiers MQTT simultanément</strong> au maximum. L’interface Web sert à la configuration et peut ensuite être arrêtée ; le service USB/MQTT continue indépendamment.</p><p><a href="https://github.com/rockbaer2007/usb-extender-home-assistant" target="_blank" rel="noreferrer">GitHub / README allemand et anglais</a> · <a href="https://github.com/rockbaer2007/usb-extender-home-assistant/releases/tag/v0.1.5" target="_blank" rel="noreferrer">ZIP 0.1.5</a> · <a href="https://github.com/rockbaer2007/usb-extender-home-assistant/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">Modifications</a></p><p>Il s’agit d’un programme autonome pour Raspberry Pi, pas d’une application HA à installer dans le magasin, ni d’un logiciel officiel de Home Assistant ou Elgato. Ce n’est <strong>pas un tunnel USB sur IP</strong> : les imprimantes et caméras ne sont pas transmises comme périphériques USB distants.</p><p>Les captures fournies par l’utilisateur proviennent du montage réel en 0.1.5. L’interface est actuellement en allemand. Cliquer sur les images larges pour les ouvrir à leur taille d’origine.</p><p><a href="/images/usb-extender/key-list.png"><img src="'+s+'" alt="Liste large des touches et groupes de canaux MQTT"></a></p><h2 id="hardware" tabindex="-1">Quels périphériques sont détectés ? <a class="header-anchor" href="#hardware" aria-label="Permalink to &quot;Quels périphériques sont détectés ? {#hardware}&quot;">​</a></h2><p><strong>Détecté</strong> signifie d’abord que Linux peut répertorier le périphérique USB. <strong>Utilisable</strong> exige aussi un pilote capable de lire ses entrées et votre autorisation explicite dans l’application. Ce sont deux capacités distinctes.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Périphérique</th><th>Fonctions prévues</th><th>Vérification</th></tr></thead><tbody><tr><td>Claviers USB, y compris claviers multimédias Windows</td><td>Codes de touches, appui/relâchement, bascule, état d’appui, clic/double-clic/appui long</td><td>Claviers Trust/HCT utilisés dans le montage réel</td></tr><tr><td>Touches de volume et multimédias</td><td><code>KEY_VOLUMEUP</code>, <code>KEY_VOLUMEDOWN</code>, <code>KEY_MUTE</code> ; autres touches de lecture/piste signalées par le matériel</td><td>Volume/muet observés ; autres touches à tester par modèle</td></tr><tr><td>Claviers à macros HID et pédales USB</td><td>Même traitement si Linux fournit des codes de touches ordinaires</td><td>Selon le modèle ; retours bienvenus</td></tr><tr><td>Elgato Stream Deck physiques</td><td>Pilote HID dédié ; fonctions d’affichage et d’entrée ci-dessous</td><td>Implémentées ; aucun Stream Deck physique encore testé dans ce projet</td></tr><tr><td>Autres appareils à touches LCD</td><td>Entrées clavier éventuellement via HID ; affichage nécessitant le pilote du fabricant</td><td>Aucune compatibilité générale garantie</td></tr><tr><td>Imprimantes, caméras, stockage USB, interfaces audio, appareils série et autres contrôleurs</td><td>Inventaire ; fonctions particulières nécessitant des adaptateurs spécifiques</td><td>Pas de transmission générale d’impression, caméra, audio, MIDI ou série</td></tr><tr><td>Stream Deck Mobile / application sur tablette</td><td>Ce n’est pas un périphérique USB directement connecté au Pi</td><td>Non intégré actuellement</td></tr></tbody></table></div><p>Un appareil répertorié n’est pas automatiquement activé. Dans <strong>USB-Geräte</strong>, attribuer un nom, cocher <strong>Gerät für Eingaben freigeben</strong>, puis choisir les courtiers destinataires. Les appareils sans numéro de série sont identifiés par leur port USB ; un changement de port peut nécessiter une nouvelle affectation.</p><p><a href="/images/usb-extender/devices.png"><img src="'+t+`" alt="Inventaire USB et autorisation explicite des entrées"></a></p><h2 id="installation" tabindex="-1">Installation sur le Pi <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation sur le Pi {#installation}&quot;">​</a></h2><p>Configuration conseillée : Raspberry Pi 4, Raspberry Pi OS Lite <strong>64 bits, Bookworm ou ultérieur</strong>, Python 3.11+, systemd, sudo et Internet pour apt/PyPI. Plusieurs appareils avec écran peuvent nécessiter un hub USB alimenté séparément. Le système Pi OS 32 bits n’a pas encore été validé en pratique.</p><p>Copier le ZIP sur le Pi, ouvrir un terminal dans son dossier de téléchargement et lancer :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unzip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unzip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> USB-Extender-Home-Assistant-0.1.5-Raspi4.zip</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> USB-Extender-Home-Assistant-0.1.5</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>L’installateur présente neuf étapes, vérifie les dépendances et installe les paquets manquants. Lors d’une mise à jour, il sauvegarde les données existantes dans <code>/var/backups/</code> et conserve réglages et icônes. Le ZIP n’est pas une image système entièrement utilisable hors ligne. Pour une mise à jour, extraire le nouveau ZIP séparément et lancer son installateur.</p><p>Définir un mot de passe Web lors de la première configuration ; aucun mot de passe par défaut n’est installé. Au besoin : <code>sudo usb-extender password</code>. Puis :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Ouvrir <code>http://&lt;adresse-du-Pi&gt;:8098</code> dans le navigateur et se connecter. Remplacer les adresses d’exemple des captures par celles de vos courtiers. Utiliser HTTP uniquement dans un réseau local de confiance, sinon prévoir VPN/HTTPS. Ne pas exposer directement l’interface sur Internet.</p><h2 id="setup" tabindex="-1">Configurer les courtiers et apprendre les touches <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Configurer les courtiers et apprendre les touches {#setup}&quot;">​</a></h2><ol><li>Dans <strong>MQTT-Broker</strong>, saisir hôte, port et identifiants éventuels. Activer les connexions souhaitées et enregistrer. Chaque courtier dispose de sa connexion ; une touche peut envoyer aux trois.</li><li>Activer la découverte pour HA. Pour ioBroker, choisir <strong>Aus – nur MQTT-Daten senden</strong> afin que son adaptateur de découverte HA ne signale pas de déclencheurs non pris en charge.</li><li>Dans <strong>USB-Geräte</strong>, nommer et autoriser l’appareil, choisir ses cibles et enregistrer.</li><li>Dans <strong>Tasten &amp; Anzeigen</strong>, choisir l’appareil puis <strong>Anlernen starten</strong>. Appuyer et relâcher chaque touche souhaitée. Les répétitions et touches déjà présentes ne créent pas de doublons.</li><li>Choisir <strong>Anlernen beenden → Tasten übernehmen → Speichern</strong>. Les nouvelles lignes sont alors actives. Pendant l’apprentissage, l’appareil sélectionné n’envoie aucune action MQTT.</li><li>Modifier les cases des canaux, les topics ou les noms par ligne. <strong>Bearbeiten</strong> ouvre le choix des courtiers, le comportement Switch et les délais. Les nouveaux canaux supplémentaires des lignes existantes sont initialement désactivés ; les nouvelles touches apprises ont tous les canaux préparés.</li></ol><p><a href="/images/usb-extender/brokers.png"><img src="`+a+'" alt="Trois profils de courtiers dans le montage réel"></a></p><p><a href="/images/usb-extender/learning.png"><img src="'+i+'" alt="Mode d’apprentissage avec appareil USB sélectionné"></a></p><p>Si le navigateur se ferme pendant l’apprentissage, la pause expire au plus tard après 15 secondes sans nouvelle confirmation. Les brouillons d’apprentissage restent uniquement dans le navigateur jusqu’à leur application et enregistrement. Les affectations déjà enregistrées sont conservées.</p><h2 id="topics" tabindex="-1">Topics et fonctions des touches <a class="header-anchor" href="#topics" aria-label="Permalink to &quot;Topics et fonctions des touches {#topics}&quot;">​</a></h2><p>Le nom <strong>Trust1</strong> et la touche <strong>F1</strong> donnent par exemple <code>trust1-key-f1/press</code>. Les noms sont adaptés à MQTT ; les caractères allemands de « Büro » deviennent <code>buero</code>. Les noms identiques reçoivent au besoin <code>-2</code>, <code>-3</code>, etc. Les topics enregistrés restent stables après un changement de nom et sont identiques sur tous les courtiers choisis. Ils sont modifiables individuellement.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Suffixe après <code>trust1-key-f1</code></th><th>Valeur et fonction</th></tr></thead><tbody><tr><td><code>/press</code></td><td><code>press</code> immédiatement à l’appui</td></tr><tr><td><code>/release</code></td><td><code>release</code> au relâchement</td></tr><tr><td><code>/press-plus</code>, <code>/release-plus</code></td><td>Même action, puis message vide après 50 ms sur ce canal</td></tr><tr><td><code>/switch</code></td><td>Premier appui <code>ON</code>, suivant <code>OFF</code> ; relâcher ne change rien</td></tr><tr><td><code>/state</code></td><td>Touche enfoncée <code>ON</code>, relâchée <code>OFF</code></td></tr><tr><td><code>/button</code></td><td><code>click</code>, <code>double_click</code> ou <code>hold</code> selon le geste</td></tr><tr><td><code>/button-plus</code></td><td>Même action Button, puis vide après 50 ms</td></tr><tr><td><code>/click</code>, <code>/double-click</code>, <code>/hold</code></td><td>Le geste individuel correspondant</td></tr></tbody></table></div><p>Le mot <code>plus</code> est écrit en toutes lettres, car <code>+</code> est un caractère générique MQTT. Les onze canaux sont activables séparément. Seuls les canaux Plus reviennent au vide ; vide ne signifie <strong>pas</strong> relâchement physique. Les valeurs Switch sont conservées dans <code>switches.json</code> après un redémarrage et resynchronisées à la reconnexion.</p><p><strong>Clic/double-clic/appui long :</strong> un clic attend la fenêtre de double-clic (300 ms après relâchement par défaut). Un second clic dans cette fenêtre produit uniquement <code>double_click</code>. Un appui de 700 ms produit <code>hold</code> une fois, sans clic au relâchement. Maintenir le second appui remplace la séquence en attente par Hold. Les délais sont réglables par touche. La répétition native du clavier ne compte pas comme nouveau clic ou nouvel appui sur Switch.</p><p><strong>Volume :</strong> les canaux Press/Press+ actifs peuvent se répéter pendant l’appui, par défaut après 500 ms toutes les 150 ms. Le relâchement arrête la répétition ; une limite de sécurité de 30 secondes s’applique aussi. L’automatisation HA ou la logique ioBroker définit le pas de volume. Press/Release restent immédiats, indépendamment de la reconnaissance différée des gestes Button.</p><p>Les messages utilisent QoS 0 sans Retain. Les entrées hors connexion ne sont pas rejouées. Plusieurs canaux actifs peuvent déclencher plusieurs automatisations associées ; choisir le canal adapté à la fonction unique souhaitée.</p><h2 id="integration" tabindex="-1">Affichage dans Home Assistant et ioBroker <a class="header-anchor" href="#integration" aria-label="Permalink to &quot;Affichage dans Home Assistant et ioBroker {#integration}&quot;">​</a></h2><p>La découverte HA regroupe toutes les touches sous le nom choisi avec un identifiant stable commun. Les actions sont des déclencheurs d’appareil avec filtrage de valeur. Switch et l’état d’appui sont des <strong>capteurs binaires</strong> indiquant un état ; commander un autre appareil nécessite une automatisation ou une affectation.</p><img src="'+n+'" alt="HA indique Switch activé et état d’appui désactivé après relâchement" width="280"><p>Dans la capture utilisateur, Switch est <strong>activé</strong> après l’appui et l’état d’appui est <strong>désactivé</strong> après relâchement. Des valeurs inconnues peuvent apparaître avant le premier message d’état reçu ; cela ne prouve pas une détection défectueuse.</p><details><summary>Avant les premiers messages d’état</summary><img src="'+r+'" alt="États HA avant réception des premières valeurs des touches" width="280"></details><p>Dans ioBroker, les points de données séparés apparaissent sous l’adaptateur MQTT à la première réception de chaque topic. La capture montre des valeurs simples : <code>press</code>, <code>release</code>, <code>click</code>, <code>hold</code>, <code>ON</code> et <code>OFF</code>. Les canaux Plus affichent ici <code>(null)</code> après leur remise à vide. C’est attendu ; le point de données reste présent. Un point double-clic apparaît seulement après l’envoi du message correspondant. Les anciens points contenant l’événement JSON initial ne sont pas modifiés automatiquement. Les configurations de découverte restent volontairement en JSON.</p><p><a href="/images/usb-extender/iobroker-states.png"><img src="'+o+`" alt="Points de données ioBroker séparés avec valeurs simples"></a></p><h2 id="stream-deck" tabindex="-1">Stream Deck et appareils similaires <a class="header-anchor" href="#stream-deck" aria-label="Permalink to &quot;Stream Deck et appareils similaires {#stream-deck}&quot;">​</a></h2><p>Le pilote intégré <code>python-elgato-streamdeck</code> 0.10.0 connaît notamment Original/MK.2, Mini, XL, Neo, Pedal et Plus. Cette liste décrit le pilote, <strong>pas des essais matériels physiques déjà effectués</strong> dans ce projet.</p><ul><li>Touches avec écran : icônes/texte personnels, luminosité par appareil, retour d’état MQTT pour changer une icône et commandes d’affichage ciblées.</li><li>Touches : Press/Release, clic/double-clic/appui long, Switch et état d’appui comme ci-dessus.</li><li>Molettes présentes : sens de rotation et appui comme entrées.</li><li>Écran tactile présent : événements tactiles ; pas d’éditeur d’écran librement composé.</li><li>Pedal et autres modèles sans écran : entrées, mais pas d’icônes sur touches d’affichage.</li><li>Une disposition fixe ; changement de profil/page et icônes animées restent à réaliser.</li></ul><p>Dans <strong>Iconbibliothek</strong>, importer des images ou un dossier situé sur le Pi. Les archives ZIP et <code>.streamDeckIconPack</code> disponibles localement sont également acceptées. Aucun téléchargement automatique depuis le Marketplace Elgato. Respecter les droits de chaque pack ; l’application utilise la première image d’une animation.</p><p>Pour un appareil ressemblant à un Stream Deck, la partie clavier peut déjà fonctionner via HID. LCD, tactile et commandes propres au fabricant peuvent nécessiter un adaptateur dédié. Merci de tester un modèle précis et de décrire les résultats plutôt que de supposer une compatibilité complète d’après son aspect.</p><h2 id="operation" tabindex="-1">Arrêter l’interface Web et sauvegarder <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Arrêter l’interface Web et sauvegarder {#operation}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ugso-usbhub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><code>web stop</code> ferme le service HTTP ; fermer le navigateur seul ne le fait pas. Le service USB/MQTT continue. Réglages, icônes et valeurs Switch se trouvent dans <code>/var/lib/ugso-usbhub/</code>. Les dix versions précédentes de configuration sont sauvegardées automatiquement ; une sauvegarde CLI complète inclut aussi icônes et valeurs Switch. Ne pas publier les sauvegardes.</p><p><a href="/images/usb-extender/system.png"><img src="`+l+'" alt="Commandes système et diagnostic"></a></p><h2 id="tests" tabindex="-1">Qu’est-ce qui est démontré en pratique ? <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Qu’est-ce qui est démontré en pratique ? {#tests}&quot;">​</a></h2><p>Les captures utilisateur montrent 0.1.5, trois profils MQTT indiqués en ligne, des touches de fonction apprises, des états HA et des points ioBroker individuels. Le journal montre la remise des publications à HA, IOB et Testserver. Cette indication seule ne prouve pas leur réception sur chaque courtier ; les captures HA/ioBroker apportent une preuve visible supplémentaire. Toutes les fonctions ne sont pas pour autant testées sur chaque appareil.</p><p><a href="/images/usb-extender/events.png"><img src="'+p+'" alt="Événements F12 avec topics sélectionnés et trois destinations MQTT"></a></p><p>En complément, 61 tests Python locaux et deux vérifications JavaScript/DOM réussissent, notamment double-clic, persistance Switch après redémarrage, routage et erreurs. Le test d’un Stream Deck physique reste ouvert.</p><h2 id="feedback" tabindex="-1">Tester votre matériel et faire un retour <a class="header-anchor" href="#feedback" aria-label="Permalink to &quot;Tester votre matériel et faire un retour {#feedback}&quot;">​</a></h2><p>Vous possédez un Stream Deck, un appareil à touches LCD similaire, un clavier à macros ou une pédale USB ? Testez-le et <a href="https://github.com/rockbaer2007/usb-extender-home-assistant/issues/new?template=hardware-test.yml" target="_blank" rel="noreferrer">communiquez les résultats sur GitHub</a>. Les signalements d’erreurs et contributions sont bienvenus.</p><p>Indiquer modèle/révision, modèle du Pi, système et version de l’application. Distinguer inventaire et vrais codes de touches. Décrire séparément appui/ relâchement, clic/double-clic/appui long, icônes/texte, luminosité, molettes, tactile et débranchement/rebranchement ; préciser les fonctions non testées. Commencer par un topic MQTT sans risque et sans action sur des appareils réels. Les captures de l’inventaire et des événements aident. Ne pas publier de mots de passe, jetons, <code>config.json</code> ou archives de sauvegarde.</p>',55)])])}const C=d(m,[["render",g]]);export{y as __pageData,C as default};
